      "causa_raiz": "No frame 160, o tempo de CPU atingiu 402.50ms, superando o orçamento de 16.7ms/frame. A pilha de execução aponta StressTestScene.Update() como o principal causador, registrando 21.33ms na fatia de execução de scripts capturada. A chamada contínua a GameObject.FindObjectsOfType<GameObject>() dentro de um laço de repetição força a CPU a varrer todos os objetos ativos na hierarquia a cada frame, gerando sobrecarga massiva de processamento.",
      "codigo_refatorado": "using System;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = true;
        public bool stressCpu = true;
        public bool stressDraw = false;
        public GameObject testPrefab;
        [Range(1, 20)] public float spawnRadius = 10f;
        [Range(1, 50)] public int cubesPerFrame = 1;
        public bool useUniqueMaterials = false;
        [Range(1, 512)] public int cpuScansPerFrame = 1;
        public int emptyObjects = 0;
        public int gcConcatIterations = 1000;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;
        [Range(0, 2000)] public int prepopulateCount = 0;

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++) new GameObject("Empty_" + i);

            if (overdrawLayers > 0 && overdrawMaterial != null) BuildOverdrawLayers();
        }

        private void BuildOverdrawLayers()
        {
            Camera cam = Camera.main;
            if (cam == null) return;
            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;
            for (int i = 0; i < overdrawLayers; i++)
            {
                float d = cam.nearClipPlane + 0.05f + i * 0.001f;
                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;
                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);
                Destroy(quad.GetComponent<Collider>());
                quad.name = "Overdraw_" + i;
                quad.transform.SetParent(cam.transform, false);
                quad.transform.localPosition = new Vector3(0f, 0f, d);
                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);
                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;
            }
        }

        private void Update()
        {
            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++) SpawnOne();
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(
                testPrefab,
                UnityEngine.Random.insideUnitSphere * spawnRadius,
                Quaternion.identity);

            if (useUniqueMaterials)
            {
                var renderer = clone.GetComponent<Renderer>();
                if (renderer != null)
                {
                    renderer.material.color = new Color(
                        UnityEngine.Random.value,
                        UnityEngine.Random.value,
                        UnityEngine.Random.value);
                }
            }
        }
    }
}",
      "explicacao_didatica": "O método Update() é executado automaticamente em todos os quadros (frames) do jogo. No código original, foram executadas operações pesadas dentro desse ciclo, especificamente a função GameObject.FindObjectsOfType, que percorre toda a árvore de objetos da cena procurando instâncias ativas. Fazer isso repetidas vezes a cada quadro consome ciclos preciosos do processador (CPU), tornando impossível manter a taxa de 60 quadros por segundo (onde cada quadro deve levar no máximo 16.7 milissegundos). A remoção dessas buscas e de operações desnecessárias no Update libera a CPU para manter a taxa de quadros estável."
    }
  ],
  "dicas_level_design": null
}

